def transform(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    for i in range(h-1):
        for j in range(w-1):
            if g[i][j]==g[i][j+1]==g[i+1][j]==g[i+1][j+1]!=0:
                marks={}
                for di,dj in ((-1,-1),(-1,2),(2,-1),(2,2)):
                    r,c=i+di,j+dj
                    if 0<=r<h and 0<=c<w and g[r][c]!=0:
                        marks[(di,dj)]=(g[r][c],r,c)
                # rotate: TL gets BL, TR gets TL, BL gets BR, BR gets TR
                rot={(-1,-1):(2,-1),(-1,2):(-1,-1),(2,-1):(2,2),(2,2):(-1,2)}
                for corner,(di,dj) in rot.items():
                    if corner not in marks: continue
                    col,mr,mc=marks[corner]
                    dr=1 if dj==2 else -1
                    dc=1 if di==2 else -1
                    # erase the original marker cell
                    g[mr][mc]=0
                    r,c=i+di,j+dj
                    while 0<=r<h and 0<=c<w:
                        if g[r][c]!=2: g[r][c]=col
                        r+=dr; c+=dc
    return g

